package net.civeira.phylax.features.document.snippetasset.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.document.snippetasset.domain.SnippetAsset;
import net.civeira.phylax.features.document.snippetasset.domain.valueobject.ContentVO;

@RequiredArgsConstructor
public class ContentValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ContentVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param content
   * @return
   */
  public T content(ContentVO content) {
    this.value = Optional.of(content);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param content
   * @return
   */
  public T content(Optional<ContentVO> content) {
    this.value = content;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param content
   * @return
   */
  public T content(String content) {
    this.value = Optional.of(ContentVO.from(content));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getContent() {
    return value.map(ContentVO::getContent);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ContentVO> getContentValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ContentVO readContent(final Optional<SnippetAsset> original,
      final ConstraintFailList fails) {
    ContentVO result = value.orElse(original.map(SnippetAsset::getContentValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "content", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetContent() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetContentIfMatches(final String field) {
    if ("content".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
